const urls=["https://www.mouser.ch/en/ProductDetail/STMicroelectronics/TIP36C?qs=JV7lzlMm3yLzusij15X%2FdA%3D%3D","https://www.mouser.ch/en/ProductDetail/onsemi/TIP36CG?qs=xZq1yRCsb1dOFJSHG5v8%252Bg%3D%3D","https://www.mouser.ch/en/ProductDetail/STMicroelectronics/TIP36CW?qs=kndcJBrKlnTEJ1eWtHtNzw%3D%3D"];
const out=[];
for(const u of urls){const r=await fetch(u);const t=await r.text();const d=new DOMParser().parseFromString(t,'text/html');const txt=d.body.innerText.replace(/\s+/g,' ');const m=txt.match(/Package \/ Case:?[^A-Z]{0,5}[A-Za-z0-9\- ]{0,30}/);out.push([r.status,u.split('/')[5],m&&m[0],(txt.match(/Mouser #:?\s*\S+/)||[])[0],(txt.match(/Mfr\. #:?\s*\S+/)||[])[0]]);}
out

